INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Besteht eine IPv6-Adresse aus 128 Bit?', 2, '[{"text": "Ja", "correct": true, "because": "IPv6 verwendet 128 Bit"}, {"text": "Nein", "correct": false, "because": "128 Bit ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wird eine IPv6-Adresse in Dezimalform wie IPv4 geschrieben?', 2, '[{"text": "Nein", "correct": true, "because": "IPv6 nutzt Hexadezimalschreibweise"}, {"text": "Ja", "correct": false, "because": "IPv4 nutzt Dezimal, IPv6 nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine IPv6-Adresse Nullen auslassen, um kürzer zu sein?', 2, '[{"text": "Ja", "correct": true, "because": "Nullenkomprimierung ist erlaubt (z. B. ::)"}, {"text": "Nein", "correct": false, "because": "Komprimierung ist eine IPv6-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Doppelpunkte das Trennzeichen in einer IPv6-Adresse?', 2, '[{"text": "Ja", "correct": true, "because": "IPv6 nutzt Doppelpunkte (z. B. 2001:0db8::1)"}, {"text": "Nein", "correct": false, "because": "Doppelpunkte sind Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine IPv6-Adresse immer 8 Blöcke enthalten?', 2, '[{"text": "Nein", "correct": true, "because": "Nullenkomprimierung kann Blöcke reduzieren"}, {"text": "Ja", "correct": false, "because": "Komprimierung erlaubt weniger sichtbare Blöcke"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Wie viele Bits hat eine IPv6-Adresse?', 2, '[{"text": "128 Bit", "correct": true, "because": "IPv6 ist auf 128 Bit ausgelegt"}, {"text": "32 Bit", "correct": false, "because": "Das ist IPv4"}, {"text": "64 Bit", "correct": false, "because": "Zu wenig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schreibweise ist für eine IPv6-Adresse korrekt?', 3, '[{"text": "2001:0db8:0000:0000:0000:0000:0000:0001", "correct": true, "because": "Hexadezimal mit 8 Blöcken ist gültig"}, {"text": "192.168.1.1", "correct": false, "because": "Das ist IPv4"}, {"text": "2001-0db8-0000-0001", "correct": false, "because": "Falsche Trennzeichen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Hexadezimalblöcke hat eine vollständige IPv6-Adresse ohne Komprimierung?', 2, '[{"text": "8", "correct": true, "because": "IPv6 hat 8 Blöcke à 16 Bit"}, {"text": "4", "correct": false, "because": "Zu wenig"}, {"text": "16", "correct": false, "because": "Zu viele"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Regel gilt für die Nullenkomprimierung in IPv6?', 2, '[{"text": "Folgen von 0000 können durch :: ersetzt werden", "correct": true, "because": "Nur einmal pro Adresse erlaubt"}, {"text": "Jeder Block kann beliebig gekürzt werden", "correct": false, "because": "Regeln sind strikt"}, {"text": "Komprimierung ist verboten", "correct": false, "because": "Sie ist erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Zeichen werden in einer IPv6-Adresse verwendet?', 2, '[{"text": "0-9 und a-f", "correct": true, "because": "Hexadezimal nutzt diese Zeichen"}, {"text": "0-255", "correct": false, "because": "Das ist IPv4-Dezimal"}, {"text": "Nur Buchstaben", "correct": false, "because": "Zahlen sind enthalten"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat das IPv6-Adressformat?', 4, '[{"text": "128 Bit lang", "correct": true, "because": "IPv6 nutzt 128 Bit"}, {"text": "8 Hexadezimalblöcke", "correct": true, "because": "Standard ohne Komprimierung"}, {"text": "Dezimalschreibweise", "correct": false, "because": "IPv6 nutzt Hexadezimal"}, {"text": "Doppelpunkt als Trennzeichen", "correct": true, "because": "Trennt die Blöcke"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beispiele sind gültige IPv6-Adressen?', 3, '[{"text": "2001:0db8::1", "correct": true, "because": "Komprimierung ist korrekt"}, {"text": "192.168.1.1", "correct": false, "because": "Das ist IPv4"}, {"text": "fe80::1", "correct": true, "because": "Gültige Link-Local-Adresse"}, {"text": "2001:0db8:0000:0000:0000:0000:0000:0001", "correct": true, "because": "Vollständig korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der IPv6-Nullenkomprimierung erlaubt?', 4, '[{"text": "Folgen von 0000 durch :: ersetzen", "correct": true, "because": "Einmal pro Adresse erlaubt"}, {"text": "Mehrere :: in einer Adresse", "correct": false, "because": "Nur ein :: erlaubt"}, {"text": "Anfangsnullen in Blöcken weglassen", "correct": true, "because": "z. B. 0db8 wird db8"}, {"text": "Beliebige Blöcke auslassen", "correct": false, "because": "Regeln sind strikt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aussagen treffen auf das IPv6-Adressformat zu?', 3, '[{"text": "128 Bit insgesamt", "correct": true, "because": "Definition von IPv6"}, {"text": "Hexadezimalschreibweise", "correct": true, "because": "Standard für IPv6"}, {"text": "4 Oktette wie IPv4", "correct": false, "because": "IPv6 hat 8 Blöcke"}, {"text": "Trennung durch Punkte", "correct": false, "because": "Doppelpunkte sind korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Formate sind für IPv6-Adressen ungültig?', 3, '[{"text": "2001::0db8::1", "correct": true, "because": "Doppeltes :: ist verboten"}, {"text": "fe80:0000:0000:0000:0000:0000:0000:0001", "correct": false, "because": "Das ist gültig"}, {"text": "2001:0db8:gggg:0000:0000:0000:0000:0001", "correct": true, "because": "g ist kein Hexadezimalwert"}, {"text": "2001:db8::1", "correct": false, "because": "Das ist gültig"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) IPv6-Adressen haben 128 Bit. b) Sie bestehen aus 4 Blöcken.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "128 Bit ja, 8 Blöcke, nicht 4"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) IPv6 nutzt Doppelpunkte als Trennzeichen. b) IPv6-Adressen sind in Dezimalform geschrieben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Doppelpunkte ja, Dezimal nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Nullenkomprimierung mit :: ist erlaubt. b) Jedes Zeichen in IPv6 ist ein Dezimalwert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Komprimierung ja, Hexadezimal statt Dezimal"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) 2001:db8::1 ist eine gültige IPv6-Adresse. b) 2001::db8::1 ist eine gültige IPv6-Adresse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ein :: erlaubt, doppeltes :: verboten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) IPv6-Adressen haben 16 Bit pro Block. b) IPv6 kann Anfangsnullen in Blöcken weglassen.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "16 Bit pro Block, Anfangsnullen können weg (z. B. 0db8 wird db8)"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]');

